/**
 * 베르단 그레이딩 테마 데이터.
 *
 * 베르단은 **머리 위가 광원이라 위가 밝고 아래가 무겁다.** 아래 값 전부가 그 한 문장의
 * 결과이며, 카르곤(발밑 용암)과 정확히 반대 방향이다:
 *  - 비네트 코어를 **위로** 올려 저지 진창 쪽을 더 누른다(카르곤은 아래로 내렸다).
 *  - 차가운 곱연산 램프가 **아래**로 자란다(카르곤은 위로 자랐다) — 무거운 것이 아래에 있다.
 *  - 스플릿 톤 방향이 **−1** 이다: 하이라이트는 포자 안개가 산란시킨 창백한 청록, 암부는
 *    삭은 이탄의 누런 갈색. 카르곤(+1, 하이라이트가 따뜻)의 반대다.
 *
 * 유일하게 방향이 같은 것은 하단 가산인데, 이건 전역 색온도가 아니라 **저지에 고인 산성
 * 웅덩이의 반사광**이라는 국소 근거를 갖는다(지형광 레이어가 그리는 침출과 같은 색이다).
 *
 * 여기 남길 주석은 **베르단 근거**뿐이다. 메커니즘 근거는 계약·레이어에 남긴다.
 */

import type { GradeTheme } from '../../contracts/grade.js';

export const BERDAN_GRADE: GradeTheme = {
  themeId: 'berdan',
  alpha: {
    // 현대 AAA 비네트의 통상 대역(20~40%) 안쪽. 모서리 총 감쇠 0.3376 으로 상한 0.36 에서
    // 여유 0.022 — 세 항(비네트·cool·gain)이 같은 예산에서 먹으므로 이걸 올리려면 다른 둘을 줄여야 한다.
    vignette: 0.27,
    /*
     * 산성 웅덩이 반사광. 전역 따뜻함은 이 레이어에서 곱연산 gain 이 맡으므로 여기는 "저지에
     * 고인 산이 아래에서 되쏜다"는 국소 근거가 있는 최소량만 남긴다. 시차 레이어의
     * `far-bloom`·`near-drip` 도 같은 방향(+)이라 겹치면 하단이 뜬다.
     */
    warm: 0.035,
    /*
     * gain 이 색온도 분리를 떠맡으므로 이 스프라이트는 가장자리 **형상**만 담당한다.
     * 짙은 청록이라 알파 0.07 에서도 실효 감쇠가 0.0433 으로 충분하다.
     */
    cool: 0.07,
    /*
     * 상한에 붙어 있다. tint 자체가 순한(휘도 0.912) 색이라 알파를 상한까지 올려도 총 감쇠는
     * 8.8% 의 0.3 배, 즉 2.6% 에 그친다.
     */
    gain: 0.3,
    // warmth 부호 교차점이 0.85 에 오도록 맞춘 값. 더 키우면 교차점이 1 을 넘어 스플릿이
    // 아니라 전역 캐스트가 되고, `validateGradeTheme` ⑦ 이 그걸 잡는다.
    shadow: 0.042,
    // 밴딩을 깨는 최소량. 이 이상은 화면이 지저분해진다.
    grain: 0.03,
  },
  /**
   * 코어를 **위로** 올려(−0.12) 아래쪽 진창을 더 누른다. `outer` 는 최원거리 모서리(약 1.49)가
   * 거의 최대에 닿는 값이고, `inner` 0.62 는 중앙 안전 사각형의 최원점(0.586)보다 커서 전투
   * 영역에서 비네트가 정확히 0 이다.
   */
  vignette: { centerY: -0.12, inner: 0.62, outer: 1.55 },
  /** 화면 **하단 1/4** 밖으로는 한 픽셀도 밝히지 않는다(시차 레인과의 중복 해소). */
  warm: { startY: 0.5, sideFalloff: 0.5 },
  /** 램프가 아래로 자란다(topStart < topEnd) — 카르곤과 방향이 반대다. 좌우는 동일 규율. */
  cool: { topStart: 0.3, topEnd: 1, sideStart: 0.62, sideEnd: 1.05 },
  tint: {
    /** 산성 웅덩이 반사광 계열 형광 녹. 지형광 채널과 같은 색 계열이다. */
    warm: 0x6fd05a,
    /** 짙은 청록. 저지의 무거운 물그늘이며 하이라이트와 색온도를 가른다. */
    cool: 0x3f6a72,
    /** 무채에 가깝게 두어 색을 밀지 않는다. */
    grain: 0xb0b8ae,
    /**
     * 하이라이트 창백한 청록 = 포자 안개가 산란시킨 하늘빛. R 을 G·B 아래로 내린 것이
     * `warmthDirection: -1` 의 실체다(기울기 −0.0494).
     */
    gain: 0xc6f2f0,
    /**
     * 암부 누런 갈색(삭은 이탄). B=0 인 적황 계열을 고른 이유는 **채도 대비 휘도가 싸기**
     * 때문이다 — 절대 휘도 상승이 0.0169 로 예산(0.06)의 3할도 안 쓰면서 warmth 절편을
     * +0.042 확보한다.
     */
    shadow: 0xff4400,
  },
  /** 광원이 하늘이라 하이라이트가 차갑고, 빛이 닿지 않는 진창이 삭아서 따뜻하다. */
  warmthDirection: -1,
};
